export const statuses={new:'待联系',contacted:'已联系',confirmed:'已确认',shipped:'已发货',completed:'已完成',cancelled:'已取消',invalid:'无效'};
export const normalizeName=s=>String(s||'').normalize('NFKC').replace(/\s/g,'').toLowerCase();
export const normalizePhone=s=>{let v=String(s||'').normalize('NFKC').replace(/[^0-9]/g,'');return v.startsWith('886')?'0'+v.slice(3):v;};
export function matches(order,orders){return orders.filter(o=>o.id!==order.id).flatMap(o=>{const name=!!normalizeName(order.name)&&normalizeName(order.name)===normalizeName(o.name);const phone=!!normalizePhone(order.phone)&&normalizePhone(order.phone)===normalizePhone(o.phone);return name||phone?[{id:o.id,reason:name&&phone?'姓名及电话':name?'姓名':'电话'}]:[];});}
export function addOrder(orders,input){if(orders.some(o=>o.requestId===input.requestId))return orders;const o={...input,phone:normalizePhone(input.phone),status:'new',notes:'',logs:[],matches:matches(input,orders)};return [...orders,o];}
export const dateKey=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
export function seed(){const names=['林柏宇','陳俊宏','黃家豪','張志偉','吳宗翰','劉冠廷','蔡明哲','許文傑','鄭凱文','王建宏','李承恩','周政廷'];let orders=[];const now=new Date();for(let i=0;i<28;i++){const n=i%12;const at=new Date(now.getTime()-(i*5*60+12)*60000);orders.push({id:'NK-'+String(1028-i),requestId:'seed-'+i,name:names[n],phone:'090000'+String(1000+n).slice(-4),createdAt:at.toISOString(),source:['Facebook','TikTok','直接访问'][i%3],product:'龙阳丸',quantity:1,price:1389,status:Object.keys(statuses)[i%7],notes:i%4===0?'已预约晚间联系，请于 18:00 后致电。':'',ip:'192.0.2.'+(i+10),device:['iPhone · iOS · Safari','Android · Chrome','Windows · Chrome'][i%3],adId:i%3===2?'':i%3===0?'NK-FB-001':'NK-TT-002',matches:[],logs:[]});}orders=orders.sort((a,b)=>a.createdAt.localeCompare(b.createdAt));orders.forEach((o,i)=>{o.matches=matches(o,orders.slice(0,i));});return orders;}
export function csv(rows){const cell=v=>'"'+(/^[=+@\-\t\r]/.test(String(v))?"'":'')+String(v??'').replaceAll('"','""')+'"';return '\ufeff'+[['订单编号','下单时间','姓名','电话','来源','广告来源 ID','下单 IP','下单设备','状态','重粉原因','备注'],...rows.map(o=>[o.id,o.createdAt,o.name,o.phone,o.source,o.adId||'',o.ip||'',o.device||'',statuses[o.status],o.matches.map(m=>m.reason).join('、'),o.notes])].map(r=>r.map(cell).join(',')).join('\r\n');}
